import {PolygonProof,interior,nextDiagonal,anglePieces,polygonError} from './polygon-proof.js?v=11';
import {angleMark} from './angle-renderer.js?v=11';
import {screenToWorld} from './core.js?v=3.1';
import {installCanvasOwnership} from './interaction.js?v=11';
export function mountVisualProof(host,{language=()=> 'en',back}){
 const tr=(a,b)=>language()==='bm'?b:a,model=new PolygonProof();let proof=false,cutMode=false,chosen=null,hint=null,drag=null,labels=true,diagonals=true,sides=false,formula=false;
 host.insertAdjacentHTML('beforeend',`<div class="proof-head"><button id="proofBack">${tr('← Library','← Pustaka')}</button><span class="explorer-kicker">${tr('Interior angles','Sudut pedalaman')}</span><h2>${tr('Visual Proof','Bukti Visual')}</h2></div><div class="proof-controls"><label>${tr('Sides','Sisi')} <input id="proofSides" type="number" min="3" max="20" value="3" data-math-mode="integer" aria-label="${tr('Number of sides','Bilangan sisi')}"></label><button id="proofGenerate">${tr('Generate polygon','Jana poligon')}</button><button id="proofStart">${tr('Visual Proof','Bukti Visual')}</button><button id="proofReset">${tr('Reset','Tetap semula')}</button></div><p id="proofGuide" role="status"></p><div class="proof-layout"><div class="proof-scroll"><canvas id="proofCanvas" tabindex="0" aria-label="${tr('Polygon and angle proof. Drag blue vertices.','Poligon dan bukti sudut. Seret bucu biru.')}"></canvas></div><aside class="proof-side"><div class="proof-actions" hidden><button id="proofCut">${tr('Draw diagonals','Lukis pepenjuru')}</button><button id="proofMove">${tr('Move vertices','Gerakkan bucu')}</button><button id="proofUndo">${tr('Undo last diagonal','Undur pepenjuru terakhir')}</button><button id="proofClear">${tr('Clear triangulation','Kosongkan triangulasi')}</button><button id="proofHint">${tr('Hint','Petunjuk')}</button><button id="proofAuto">${tr('Auto-complete (teacher)','Lengkapkan (guru)')}</button></div><div class="proof-lever-box" hidden><span>${tr('Original shape','Bentuk asal')}</span><div id="proofLever" class="proof-lever" tabindex="0" role="slider" aria-label="${tr('Visual Proof progress','Kemajuan Bukti Visual')}" aria-valuemin="0" aria-valuemax="100" aria-orientation="vertical"><span class="proof-grip">☰</span></div><span>${tr('Pull down to reveal','Tarik ke bawah untuk dedahkan')}</span><button id="proofReplay">${tr('Replay proof','Ulang bukti')}</button></div><div class="proof-toggles"></div><label>${tr('Vertex','Bucu')} <select id="proofVertex"></select></label><div class="proof-nudge" aria-label="${tr('Move selected vertex','Gerakkan bucu dipilih')}"></div></aside></div><div id="proofSummary" class="proof-summary" hidden></div>`);
 const actions=host.querySelector('.proof-actions');host.querySelector('.proof-layout').before(actions);
 const get=id=>host.querySelector('#'+id),canvas=get('proofCanvas'),ctx=canvas.getContext('2d'),lever=get('proofLever');get('proofBack').onclick=back;
 const messages={simple:tr('Visual Proof currently supports simple polygons only. Move a vertex to uncross the edges.','Bukti Visual menyokong poligon ringkas sahaja. Gerakkan bucu supaya sisi tidak bersilang.'),degenerate:tr('Separate the vertices and avoid a flat corner.','Pisahkan bucu dan elakkan sudut rata.'),diagonal:tr('Choose two non-neighbouring vertices with a diagonal inside the polygon.','Pilih dua bucu bukan bersebelahan dengan pepenjuru di dalam poligon.'),crossing:tr('Diagonals must not cross. Try a different pair of vertices.','Pepenjuru tidak boleh bersilang. Cuba pasangan bucu lain.'),reset:tr('The changed shape needs new cuts. Triangulation has been cleared.','Bentuk berubah memerlukan potongan baharu. Triangulasi telah dikosongkan.')};
 const colours=['#df7049','#3898bb','#9769cc','#c29722','#319675','#cc6097'];
 const letter=i=>String.fromCharCode(65+i);
 function vertices(){get('proofVertex').replaceChildren(...model.points.map((_,i)=>{const o=document.createElement('option');o.value=i;o.textContent=letter(i);return o;}));}
 for(const [en,bm,initial,set]of[['Angle labels','Label sudut',true,v=>labels=v],['Diagonals','Pepenjuru',true,v=>diagonals=v],['Side labels','Label sisi',false,v=>sides=v]]){const label=document.createElement('label'),input=document.createElement('input');input.type='checkbox';input.checked=initial;input.onchange=()=>{set(input.checked);draw()};label.append(input,document.createTextNode(tr(en,bm)));host.querySelector('.proof-toggles').append(label);}
 for(const [symbol,dx,dy]of[['←',-5,0],['↑',0,-5],['↓',0,5],['→',5,0]]){const b=document.createElement('button');b.textContent=symbol;b.ariaLabel=tr('Move vertex ','Gerakkan bucu ')+symbol;b.onclick=()=>{const i=+get('proofVertex').value,p=model.points[i];model.move(i,{x:p.x+dx,y:p.y+dy});refresh()};host.querySelector('.proof-nudge').append(b);}
 function refresh(){const state=model.state;host.querySelector('.proof-actions').hidden=!proof;host.querySelector('.proof-lever-box').hidden=!proof;lever.setAttribute('aria-disabled',String(!state.complete));lever.setAttribute('aria-valuenow',String(Math.round(model.progress*100)));lever.querySelector('.proof-grip').style.top=`${model.progress*100}%`;get('proofCut').setAttribute('aria-pressed',String(cutMode));get('proofMove').setAttribute('aria-pressed',String(!cutMode));get('proofUndo').disabled=get('proofClear').disabled=!model.cuts.length;get('proofAuto').disabled=get('proofHint').disabled=!!state.error||state.complete;
 get('proofGuide').textContent=messages[model.notice]||messages[state.error]||(!proof?tr('Drag the blue vertices to explore. Choose Visual Proof when ready.','Seret bucu biru untuk meneroka. Pilih Bukti Visual apabila bersedia.'):state.complete?tr(`Great! You made ${state.faces.length} triangle(s). Pull the lever down.`,`Bagus! Anda membentuk ${state.faces.length} segi tiga. Tarik tuil ke bawah.`):tr(`Tap two vertices to draw each cut (${model.cuts.length}/${model.points.length-3}). Switch to Move vertices to edit.`,`Ketik dua bucu untuk melukis potongan (${model.cuts.length}/${model.points.length-3}). Pilih Gerakkan bucu untuk menyunting.`));
 const summary=get('proofSummary');summary.hidden=!proof||model.progress<.999||!state.complete;summary.replaceChildren();if(!summary.hidden){const n=state.faces.length,p=document.createElement('p');p.textContent=tr(`${model.points.length} sides → ${n} triangle(s). Each triangle contributes 180°.`,`${model.points.length} sisi → ${n} segi tiga. Setiap segi tiga menyumbang 180°.`);const eq=document.createElement('strong');eq.textContent=Array(n).fill('180°').join(' + ')+` = ${n*180}°`;const multiply=document.createElement('p');multiply.textContent=`${n} × 180° = ${n*180}°`;const b=document.createElement('button');b.textContent=tr(formula?'Hide formula':'Show formula',formula?'Sembunyikan rumus':'Tunjuk rumus');b.onclick=()=>{formula=!formula;refresh()};summary.append(p,eq,multiply,b);if(formula){const f=document.createElement('p');f.textContent=tr('n sides → n − 2 triangles. Interior angle sum = (n − 2) × 180°.','n sisi → n − 2 segi tiga. Jumlah sudut pedalaman = (n − 2) × 180°.');summary.append(f);}}draw();}
 let worldHeight=470,worldWidth=850;
 function draw(){const state=model.state,n=state.complete&&proof?state.faces.length:1;const width=canvas.parentElement.clientWidth;worldWidth=width<600?440:850;worldHeight=worldWidth===440?470+(proof&&state.complete&&model.progress>0?n*110:0):Math.max(470,70+n*110);const ratio=width/worldWidth,height=worldHeight*ratio,dpr=Math.min(devicePixelRatio||1,2);canvas.style.height=height+'px';canvas.width=Math.round(width*dpr);canvas.height=Math.round(height*dpr);ctx.setTransform(dpr*ratio,0,0,dpr*ratio,0,0);const ink=document.body.classList.contains('dark')?'#f2f4f8':'#243047';ctx.strokeStyle=ink;ctx.lineWidth=2;ctx.font='15px sans-serif';ctx.textAlign='center';ctx.textBaseline='middle';
 const path=ps=>{ctx.beginPath();ps.forEach((p,i)=>i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y));ctx.closePath();};
 path(model.points);ctx.fillStyle=document.body.classList.contains('dark')?'#90a9d015':'#739bcc10';ctx.fill();ctx.stroke();
 if(diagonals)for(const [a,b]of model.cuts){ctx.beginPath();ctx.moveTo(model.points[a].x,model.points[a].y);ctx.lineTo(model.points[b].x,model.points[b].y);ctx.stroke();}
 if(hint){ctx.save();ctx.strokeStyle='#d38b16';ctx.setLineDash([6,5]);ctx.beginPath();ctx.moveTo(model.points[hint[0]].x,model.points[hint[0]].y);ctx.lineTo(model.points[hint[1]].x,model.points[hint[1]].y);ctx.stroke();ctx.restore();}
 if(!polygonError(model.points))model.points.forEach((p,i)=>{const a=interior(model.points,i);ctx.strokeStyle='#000';angleMark(ctx,{...a,radius:25,fill:colours[i%colours.length]+'45',rightAngleDisplay:'marker-and-value'});if(labels){ctx.fillStyle=ink;const mid=a.start+a.sweep/2;ctx.fillText(a.degrees.toFixed(1)+'°',p.x+Math.cos(mid)*47,p.y+Math.sin(mid)*47);}});
 if(sides)model.points.forEach((p,i)=>{const q=model.points[(i+1)%model.points.length];ctx.fillStyle=ink;ctx.fillText(letter(i)+letter((i+1)%model.points.length),(p.x+q.x)/2,(p.y+q.y)/2-12);});
 if(proof&&state.complete&&model.progress>0)state.faces.forEach((face,j)=>{const target=worldWidth===440?{x:220,y:530+j*110}:{x:650,y:105+j*110};const centre=face.reduce((s,i)=>({x:s.x+model.points[i].x/3,y:s.y+model.points[i].y/3}),{x:0,y:0}),dx=(centre.x-220)*.12*Math.min(1,model.progress/.25),dy=(centre.y-230)*.12*Math.min(1,model.progress/.25);ctx.save();ctx.globalAlpha=1-model.progress*.85;ctx.strokeStyle=ink;path(face.map(i=>({x:model.points[i].x+dx,y:model.points[i].y+dy})));ctx.stroke();ctx.restore();
 for(const a of anglePieces(model.points,face,model.progress,target)){ctx.save();ctx.strokeStyle='#000';ctx.lineWidth=1.2;angleMark(ctx,{...a,radius:35,fill:colours[a.vertex%colours.length]+'b0',rightAngleDisplay:'marker-and-value'});ctx.restore();}
 if(model.progress>=.999){ctx.strokeStyle=ink;ctx.beginPath();ctx.moveTo(target.x-52,target.y);ctx.lineTo(target.x+52,target.y);ctx.stroke();ctx.fillStyle=ink;ctx.fillText(`${j+1}: 180°`,target.x,target.y+23);}});
 model.points.forEach((p,i)=>{ctx.beginPath();ctx.arc(p.x,p.y,chosen===i?11:8,0,Math.PI*2);ctx.fillStyle=chosen===i?'#edaa31':'#4c91ff';ctx.fill();ctx.strokeStyle=ink;ctx.stroke();ctx.fillStyle=ink;ctx.fillText(letter(i),p.x,p.y-19);});
 }
 const pos=e=>{const r=canvas.getBoundingClientRect();return screenToWorld({x:e.clientX-r.left,y:e.clientY-r.top},{x:0,y:0,zoom:r.width/worldWidth})};
 const owner=installCanvasOwnership(canvas,()=>drag=null);
 canvas.onpointerdown=e=>{if(e.button!==0||!owner.allowed()||drag)return;const p=pos(e),i=model.points.findIndex(q=>Math.hypot(q.x-p.x,q.y-p.y)<20/(canvas.clientWidth/worldWidth));if(i<0)return;e.preventDefault();canvas.setPointerCapture(e.pointerId);get('proofVertex').value=i;drag={id:e.pointerId,index:i,start:p,cut:proof&&cutMode,moved:false};};
 canvas.onpointermove=e=>{if(drag?.id!==e.pointerId)return;const p=pos(e);if(!drag.moved&&Math.hypot(p.x-drag.start.x,p.y-drag.start.y)<5)return;drag.moved=true;model.move(drag.index,{x:Math.max(24,Math.min(420,p.x)),y:Math.max(30,Math.min(435,p.y))});hint=null;refresh();};
 const end=e=>{if(drag?.id!==e.pointerId)return;if(e.type==='pointerup'&&drag.cut&&!drag.moved){if(chosen===null)chosen=drag.index;else{model.add(chosen,drag.index);chosen=null;hint=null;}refresh();}drag=null};canvas.onpointerup=end;canvas.onpointercancel=end;canvas.onlostpointercapture=end;
 let leverPointer=null;const scrub=e=>{const r=lever.getBoundingClientRect();model.scrub((e.clientY-r.top)/r.height);refresh();};lever.onpointerdown=e=>{if(!model.state.complete)return;e.preventDefault();leverPointer=e.pointerId;lever.setPointerCapture(e.pointerId);scrub(e)};lever.onpointermove=e=>{if(e.pointerId===leverPointer)scrub(e)};lever.onpointerup=lever.onpointercancel=lever.onlostpointercapture=()=>leverPointer=null;lever.onkeydown=e=>{const change={ArrowDown:.05,ArrowUp:-.05,PageDown:.2,PageUp:-.2}[e.key];if(change!==undefined||['Home','End'].includes(e.key)){e.preventDefault();model.scrub(e.key==='Home'?0:e.key==='End'?1:model.progress+change);refresh();}};
 get('proofGenerate').onclick=()=>{const n=Number(get('proofSides').value);if(!Number.isInteger(n)||n<3||n>20)return;model.reset(n);chosen=hint=null;formula=false;vertices();refresh()};get('proofReset').onclick=()=>{model.reset(model.points.length);chosen=hint=null;formula=false;vertices();refresh()};get('proofStart').onclick=()=>{proof=true;cutMode=!model.state.complete;refresh()};get('proofCut').onclick=()=>{cutMode=true;chosen=null;refresh()};get('proofMove').onclick=()=>{cutMode=false;chosen=null;refresh()};get('proofUndo').onclick=()=>{model.cuts.pop();model.progress=0;chosen=hint=null;refresh()};get('proofClear').onclick=()=>{model.cuts=[];model.progress=0;chosen=hint=null;refresh()};get('proofHint').onclick=()=>{hint=nextDiagonal(model.points,model.cuts);draw()};get('proofAuto').onclick=()=>{model.auto();cutMode=false;chosen=hint=null;refresh()};get('proofReplay').onclick=()=>{model.scrub(0);refresh()};vertices();const observer=new ResizeObserver(draw);observer.observe(canvas.parentElement);refresh();return()=>{observer.disconnect();owner.dispose();};
}
